import{_ as a,o,c as i,a2 as s}from"./chunks/framework.CC9cRD7J.js";const u=JSON.parse('{"title":"Congelar Jugadores (/freeze)","description":"","frontmatter":{},"headers":[],"relativePath":"moderacion/congelar-jugadores.md","filePath":"moderacion/congelar-jugadores.md","lastUpdated":1793573363000}'),n={name:"moderacion/congelar-jugadores.md"};function r(t,e,l,d,c,g){return o(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="congelar-jugadores-freeze" tabindex="-1">Congelar Jugadores (/freeze) <a class="header-anchor" href="#congelar-jugadores-freeze" aria-label="Permalink to &quot;Congelar Jugadores (/freeze)&quot;">​</a></h1><p>La función de congelamiento (Freeze) permite a los moderadores paralizar a un jugador para realizar una revisión de seguridad (Screenshare) o impedir que continúe jugando mientras se aclara una posible infracción.</p><hr><h2 id="❄️-comandos-de-congelamiento" tabindex="-1">❄️ Comandos de Congelamiento <a class="header-anchor" href="#❄️-comandos-de-congelamiento" aria-label="Permalink to &quot;❄️ Comandos de Congelamiento&quot;">​</a></h2><ul><li><strong>Congelar o descongelar a un jugador:</strong><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/freeze</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">jugado</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">r</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [enable</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">disable]</span></span></code></pre></div><em>(Permiso requerido: <code>staff.freeze</code>)</em></li><li><strong>Mediante la Hotbar:</strong> Equípate la <strong>Vara de Blaze</strong> (Slot 6) y haz clic derecho directamente sobre el jugador.</li></ul><hr><h2 id="🚫-restricciones-del-jugador-congelado" tabindex="-1">🚫 Restricciones del Jugador Congelado <a class="header-anchor" href="#🚫-restricciones-del-jugador-congelado" aria-label="Permalink to &quot;🚫 Restricciones del Jugador Congelado&quot;">​</a></h2><ol><li><strong>Movimiento Bloqueado:</strong> No puede caminar, saltar ni teletransportarse.</li><li><strong>Interacciones Prohibidas:</strong> No puede romper ni colocar bloques, ni interactuar con cofres o puertas.</li><li><strong>Protección de Combate:</strong> No puede golpear a otros jugadores ni recibir daño de terceros mientras está paralizado.</li><li><strong>Mensaje Periódico en Pantalla:</strong> Cada 5 segundos (configurable en <code>timer</code>) recibe un recordatorio acústico y un mensaje en el chat indicándole que está bajo revisión.</li><li><strong>Prompt GUI (Opcional):</strong> Si se activa <code>prompt: true</code> en <code>config.yml</code>, al jugador se le abrirá un menú bloqueando su vista con las instrucciones exactas de soporte (por ejemplo, indicaciones para unirse al Discord oficial).</li></ol><hr><h2 id="🏃-castigo-por-desconexion-logout-ban" tabindex="-1">🏃 Castigo por Desconexión (Logout Ban) <a class="header-anchor" href="#🏃-castigo-por-desconexion-logout-ban" aria-label="Permalink to &quot;🏃 Castigo por Desconexión (Logout Ban)&quot;">​</a></h2><p>Si el jugador intenta eludir la revisión saliéndose del servidor:</p><ul><li>El plugin detecta el cierre de sesión y ejecuta inmediatamente el comando configurado en <code>logout-commands</code>:<div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">logout-commands</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ban %player% Has abandonado el servidor mientras estabas congelado para revisión.&quot;</span></span></code></pre></div></li><li>Se notifica a todo el equipo de staff de la evasión.</li></ul>',12)])])}const h=a(n,[["render",r]]);export{u as __pageData,h as default};
